from pathlib import Path
exec((Path(__file__).parent/'rediger_dx8.py').read_text().split('put(1,')[0])
put(9,prose('''Point 9.a — La PPR ne possède pas de test diagnostique unique de référence. La synthèse confronte symptômes, examen, réaction inflammatoire et recherche de diagnostics concurrents.
La CRP et la VS documentent une inflammation sans en établir l’étiologie. Elles servent aussi de repères initiaux pour le suivi, avec une interprétation clinique qui devient particulièrement importante sous inhibition de l’IL-6.
Point 9.b — L’échographie des épaules et des hanches recherche une inflammation synoviale ou périarticulaire. Un résultat compatible renforce une hypothèse cohérente, sans rendre les autres causes impossibles.''','p8-diagnostic p8-bio p8-imagerie p8-eular-rechute')+
tab(['Examen','Question clinique','Résultat et limite','Conséquence'],[
(['La CRP et la VS sont mesurées.','Existe-t-il une réaction inflammatoire ?','Une élévation est fréquente mais non spécifique ; une valeur normale ne clôt pas un tableau atypique.','Rechercher la cohérence et une cause alternative si les données divergent.'],'p8-bio p8-ch-bilan'),
(['La numération sanguine est réalisée.','Une anémie ou une anomalie hématologique accompagne-t-elle les symptômes ?','Une anémie normocytaire normochrome peut accompagner la PPR.','Une anomalie inexpliquée élargit le bilan au lieu de confirmer mécaniquement la PPR.'],'p8-ch-bilan p8-dd-cancer'),
(['Les CK sont dosées si une myopathie est envisagée.','Le patient présente-t-il une atteinte musculaire primitive ?','La PPR comporte habituellement des CK normales et pas de vraie faiblesse musculaire.','Une faiblesse objective ou une élévation importante des CK conduit à une démarche de myopathie.'],'p8-dgn-ck p8-dd-myosite'),
(['Le facteur rhumatoïde et les anticorps anti-CCP orientent le diagnostic différentiel.','Une polyarthrite rhumatoïde explique-t-elle mieux le tableau ?','Une polyarthrite peut rester séronégative ; les petites articulations et leur évolution comptent.','Une synovite périphérique persistante impose de réévaluer la classification initiale.'],'p8-dd-pr p8-ch-bilan'),
(['La TSH est demandée selon le contexte.','Une hypothyroïdie participe-t-elle aux douleurs ou à la fatigue ?','Une anomalie thyroïdienne peut fournir une explication concurrente.','Interpréter avec les manifestations plutôt que substituer une étiquette endocrinienne automatique.'],'p8-dd-autres p8-ch-bilan'),
(['Glycémie, créatinine, enzymes hépatiques et analyse urinaire complètent le bilan initial.','Quel terrain modifie la sécurité du traitement ?','Ces examens n’identifient pas la PPR ; ils documentent notamment les risques métaboliques et rénaux.','Adapter la surveillance et les prescriptions au terrain identifié.'],'p8-ch-bilan aips-p8-prednisone_galepharm-6'),
(['L’échographie examine les structures des ceintures.','Existe-t-il une bursite ou une synovite compatible ?','Bursite sous-acromiale ou sous-deltoïdienne, ténosynovite bicipitale et synovite peuvent être observées.','Intégrer la distribution des lésions et la clinique, sans transformer une anomalie en preuve isolée.'],'p8-imagerie p8-score-table')])+
w(9,'Échographie : demander une question anatomique précise','''À l’épaule, l’examen recherche une bursite sous-acromiale ou sous-deltoïdienne, une ténosynovite du long biceps et une synovite glénohumérale.
À la hanche, une synovite ou une bursite trochantérienne peut compléter le tableau. L’examen peut aussi contribuer à identifier une affection concurrente.
Les critères de classification utilisent des combinaisons précises de sites ; ils ne permettent pas de baptiser PPR toute bursite isolée chez une personne âgée.
Le compte rendu doit donc être rapproché du côté douloureux, de la bilatéralité et de la limitation observée. Une anomalie d’imagerie ne remplace pas l’examen clinique.''','p8-imagerie p8-score-table p83-eular26-diagnostic')+
w(9,'Si l’on suspecte une artérite associée','''La stratégie change lorsqu’apparaissent des manifestations compatibles avec une ACG. EULAR privilégie une imagerie vasculaire rapide réalisée par une équipe expérimentée.
L’échographie constitue l’imagerie de première intention dans la recommandation EULAR sur l’ACG ; les artères temporales et axillaires font partie de l’examen standard.
La probabilité préalable et le résultat sont interprétés ensemble. Une forte probabilité avec imagerie positive peut suffire au diagnostic ; des résultats discordants demandent des investigations supplémentaires.
Une menace ischémique ne doit pas attendre la disponibilité de l’échographie ou de la biopsie. Les glucocorticoïdes débutent sans délai en cas de forte suspicion, pendant l’organisation de la confirmation.''','p83-eular23-echo p83-eular23-probabilite p83-eular23-imagerie-urgente p8-eular-r2')+
prose('''Point 9.c — Les images pédagogiques sont différées dans cette livraison. Les anomalies attendues et leur portée diagnostique sont décrites dans les fenêtres, sans image inventée.
Point 9.d — Une radiographie peut aider à rechercher une affection dégénérative ou un diagnostic concurrent ; elle ne confirme pas spécifiquement la PPR.
L’IRM peut montrer une inflammation des tissus profonds lorsque l’évaluation spécialisée la juge utile. La revue européenne ne la présente pas comme un examen systématique de toute suspicion de PPR.
La TEP au fluorodésoxyglucose peut être discutée dans des situations sélectionnées, notamment pour rechercher une vascularite des gros vaisseaux ou une autre cause d’inflammation. Elle n’est pas un examen de routine de chaque patient.
Une présentation réfractaire conduit d’abord à reconsidérer le diagnostic et l’indication des examens avec un centre spécialisé. La multiplication des examens sans question clinique ne remplace pas cette réévaluation.''','p8-radio p8-imagerie p8-eular-r10'))
put(10,prose('''La conduite commence par rechercher une urgence associée avant de traiter les douleurs des ceintures. Le point de bifurcation majeur est la suspicion d’ACG, particulièrement lorsqu’existent des manifestations ischémiques.
Sans signe d’ACG menaçante, la plupart des suspicions de PPR peuvent attendre la confirmation diagnostique avant le début des glucocorticoïdes. Le patient bénéficie néanmoins d’une évaluation spécialisée.
Un essai de corticoïdes ne remplace pas cette étape : il peut modifier rapidement les signes cliniques et les examens utilisés pour établir le diagnostic.''','p8-eular-r1 p8-eular-r2 p8-eular-no-test')+
tab(['Situation au départ','Décision','Action suivante','Condition de réévaluation'],[
(['Une baisse visuelle, une diplopie ou une claudication mandibulaire fait suspecter une ACG.','Considérer la filière urgente spécialisée.','Ne pas différer les glucocorticoïdes en cas de forte suspicion pendant que sont organisés les examens confirmatoires.','Une aggravation visuelle ou neurologique appelle une prise en charge immédiate.'],'p83-eular26-signes-urgence p8-eular-r2'),
(['Les ceintures sont douloureuses et raides sans manifestation ischémique.','Rechercher une constellation de PPR et ses imitateurs.','Documenter examen, inflammation, terrain et examens différentiels pertinents ; adresser pour confirmation spécialisée.','Toute nouvelle manifestation vasculaire change la priorité.'],'p8-diagnostic p8-ch-bilan p8-eular-r1 p8-eular-r2'),
(['Le diagnostic de PPR est confirmé.','Induire une rémission en réduisant l’exposition cumulative aux glucocorticoïdes.','Choisir le régime oral et la décroissance avec le patient, selon la recommandation EULAR et les contraintes de la notice suisse.','La persistance de symptômes ou une toxicité imposent de revoir le plan.'],'p8-eular-r3 p8-eular-remission aips-p8-prednisone_galepharm-4'),
(['La douleur réapparaît pendant la décroissance.','Évaluer une rechute sans la présumer automatiquement.','Confronter symptômes, examen, biologie et, au besoin, imagerie ; considérer aussi les diagnostics concurrents et le sevrage.','Un tableau atypique ou réfractaire est réadressé au spécialiste.'],'p8-eular-r9 p8-eular-rechute p8-eular-r10'),
(['Une rechute est retenue.','Réintroduire ou augmenter les glucocorticoïdes au moins jusqu’à la dernière dose efficace selon EULAR.','Reprendre ensuite une décroissance individualisée et discuter un traitement d’épargne chez les patients sélectionnés.','Les risques de chaque traitement et son statut réglementaire suisse restent vérifiés.'],'p8-eular-r3 p8-eular-r6 aips-p8-kevzara-3'),
(['La maladie paraît réfractaire malgré une prise en charge adaptée.','Reconsidérer le diagnostic.','Envisager une orientation vers un centre spécialisé plutôt qu’une escalade répétée sans nouvel examen.','Rechercher notamment une affection inflammatoire concurrente, une infection ou une néoplasie selon la présentation.'],'p8-eular-r10 p8-dd-pr p8-dd-cancer')])+
w(10,'Le résultat biologique n’agit pas seul','''Une CRP augmentée chez un patient redevenu fonctionnel ne constitue pas à elle seule une instruction d’augmenter la prednisone. Le contexte clinique et les autres causes d’inflammation doivent être examinés.
Inversement, un marqueur normal ne rend pas impossible une rechute, particulièrement sous un traitement qui modifie la réponse inflammatoire biologique.
La consultation distingue donc activité de la maladie, séquelles fonctionnelles, pathologie associée et effets indésirables des médicaments.''','p8-ch-suivi p8-eular-r9 p8-eular-rechute')+
w(10,'Rechute ou sevrage : conserver une démarche ouverte','''La diminution des glucocorticoïdes peut révéler une réactivation inflammatoire, mais aussi des symptômes liés à une insuffisance surrénalienne ou au sevrage.
EULAR souligne cette difficulté, particulièrement aux faibles doses. La notice suisse prévient qu’une suppression corticosurrénalienne peut persister longtemps après une exposition prolongée.
Le patient ne doit donc pas interrompre brutalement sa prescription ni improviser une alternance de doses. Le médecin réévalue le tableau et adapte le plan de façon individualisée.''','p8-eular-rechute p8-eular-taper aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6'))
put(11,prose('''11.A — Le but est une rémission sans glucocorticoïdes, avec disparition des symptômes et amélioration fonctionnelle. EULAR décrit au minimum une absence de symptômes soutenue par la normalisation des marqueurs inflammatoires, tout en reconnaissant l’absence de définition consensuelle complète de rémission.
Le repère temporel proposé est une réduction à 10 mg par jour dans un délai de un à deux mois, avec l’objectif d’arrêter les glucocorticoïdes dans l’année. Ces jalons sont adaptés à l’activité, aux rechutes et au terrain ; ils ne constituent pas une obligation de sevrage malgré une maladie active.
Le suivi porte sur les gestes qui limitaient initialement le patient, tels que s’habiller ou se lever, ainsi que sur les manifestations inflammatoires et la tolérance. Une réponse biologique sans récupération clinique demande une nouvelle analyse.''','p8-eular-r3 p8-eular-remission p8-eular-taper p8-clinique')+
prose('''11.B — Après confirmation d’une PPR, EULAR recommande des glucocorticoïdes oraux pour induire la rémission. Le choix est discuté avec le patient en tenant compte de l’efficacité attendue, des complications et des contraintes du traitement.
Les doses EULAR sont exprimées en équivalents prednisone ou prednisolone. La recommandation clinique propose une dose initiale de 15 à 25 mg par jour, puis une décroissance vers 10 mg par jour en un à deux mois.
La notice suisse Prednisone Galepharm inclut la polymyalgie rhumatismale parmi les affections rhumatismales, mais sa rubrique posologique est générale. Elle demande une adaptation individuelle et la plus faible dose efficace ; elle ne fournit pas ce schéma spécifique de PPR.
Le schéma EULAR et les règles de sécurité AIPS doivent donc être lus ensemble, sans attribuer à la notice suisse un protocole propre à la PPR qu’elle ne formule pas.''','p8-eular-r3 p8-eular-equivalence p8-eular-partage aips-p8-prednisone_galepharm-3 aips-p8-prednisone_galepharm-4')+
tab(['Élément de prescription','Cadre vérifié','Consigne pratique','Limite'],[
(['La prednisone est administrée par voie orale.','Prednisone Galepharm est disponible en comprimés avec rainures permettant les dosages nécessaires.','La prise circadienne de la dose quotidienne le matin fait partie des modalités autorisées ; les comprimés sont avalés sans mâcher pendant ou après un repas avec du liquide.','Les autres modes généraux de la notice ne deviennent pas des schémas de routine pour la PPR.'],'aips-p8-prednisone_galepharm-2 aips-p8-prednisone_galepharm-4 p8-eular-taper'),
(['L’induction est adaptée au diagnostic confirmé.','EULAR propose 15 à 25 mg par jour en équivalents prednisone ou prednisolone.','Le prescripteur choisit la dose selon maladie, comorbidités et éventuelle thérapie associée.','La plage générale AIPS de 5 à 60 mg par jour ne doit pas être présentée comme le protocole PPR.'],'p8-eular-r3 p8-eular-equivalence aips-p8-prednisone_galepharm-4'),
(['La décroissance accompagne le contrôle clinique.','Le jalon EULAR est 10 mg par jour en un à deux mois.','La suite vise la dose minimale efficace et l’arrêt dans l’année lorsque l’évolution le permet.','Une baisse rigide malgré rechute ou intolérance ne respecte pas l’individualisation recommandée.'],'p8-eular-r3 p8-eular-remission p8-eular-taper'),
(['La reprise de traitement dépend d’une rechute évaluée.','EULAR recommande au moins la dernière dose efficace, puis une nouvelle décroissance individualisée.','Documenter symptômes, examen et biologie avant d’attribuer toute douleur à la PPR.','L’insuffisance surrénalienne et les diagnostics concurrents doivent rester envisagés.'],'p8-eular-r3 p8-eular-r9 p8-eular-rechute'),
(['L’arrêt brutal est évité après une exposition prolongée.','La notice suisse précise une réduction graduelle lorsque la thérapie dépasse huit à dix jours.','Un plan écrit indique les doses et la date du prochain contrôle.','La suppression corticosurrénalienne peut persister et impose une adaptation médicale lors d’un stress important.'],'aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6')])+
w(11,'Prise matinale et décroissance : distinguer autorisation générale et recommandation PPR','''La notice admet plusieurs modalités de prise pour des maladies différentes. La recommandation EULAR spécifique à la PPR ne recommande pas en routine les glucocorticoïdes intramusculaires, les formes à libération modifiée, les doses fractionnées ou la prise un jour sur deux.
Le choix d’une prise quotidienne le matin associe une modalité autorisée dans l’AIPS à la stratégie orale utilisée pour la PPR.
Aux faibles doses, une adaptation spécialisée peut être nécessaire pour gérer la maladie et le risque surrénalien. Cette exception ne justifie pas que le patient construise seul un calendrier alterné.''','aips-p8-prednisone_galepharm-4 p8-eular-taper')+
prose('''11.C — Une PPR isolée n’impose pas un protocole de réanimation. En revanche, la suspicion d’ACG change le délai et la filière, surtout lorsque sont présents des signes ischémiques visuels.
EULAR recommande que toute suspicion d’ACG soit évaluée par un spécialiste dans les vingt-quatre heures ; des manifestations ischémiques ou visuelles peuvent nécessiter une intervention immédiate.
En cas de forte suspicion d’ACG, les glucocorticoïdes commencent sans délai pendant l’organisation de la confirmation. Le schéma oral de PPR ne doit pas être utilisé comme substitut au traitement spécialisé d’une ACG menaçant la vision.
Une suspicion d’infection sévère, un état général rapidement dégradé ou une possible insuffisance surrénalienne sous traitement demande aussi une évaluation urgente. L’augmentation empirique répétée de prednisone peut masquer une infection.''','p83-eular26-orientation p83-eular26-signes-urgence p8-eular-r2 aips-p8-prednisone_galepharm-6')+
w(11,'Traitement d’épargne : recommandation européenne et statut suisse ne se confondent pas','''EULAR envisage le tocilizumab chez certains patients avec PPR récente. Dans des PPR sélectionnées rechutantes ou réfractaires, la recommandation privilégie un inhibiteur du récepteur de l’IL-6, notamment le sarilumab, avec le tocilizumab comme alternative.
Le méthotrexate peut être une autre option dans ces groupes. Ces traitements relèvent d’une décision spécialisée tenant compte des contre-indications, de la surveillance et du statut réglementaire.
La notice suisse de Kevzara consultée indique la polyarthrite rhumatoïde, sans indication PPR. Une recommandation EULAR sur la PPR ne transforme donc pas son utilisation en prescription autorisée dans cette indication en Suisse.
Le texte européen précise aussi l’absence d’autorisation du tocilizumab dans la PPR au moment de son analyse. Aucune dose issue du protocole de polyarthrite rhumatoïde n’est transposée ici à la PPR.''','p8-eular-r6 p8-eular-il6-ch aips-p8-kevzara-3')+
prose('''11.D — Avant une corticothérapie prolongée, le médecin vérifie les infections actuelles ou latentes, les médicaments associés, le risque osseux, la glycémie, la pression artérielle et les antécédents oculaires ou psychiatriques.
L’hypersensibilité à la prednisone ou aux composants est une contre-indication. La notice énumère aussi des contre-indications à l’utilisation prolongée, dont certaines infections virales, mycoses systémiques, parasitoses et l’hépatite B active non traitée par antiviraux.
La notice mentionne le glaucome dans les contre-indications et le reprend dans les précautions particulières comme contre-indication relative. Cette formulation impose une clarification clinique spécialisée ; elle ne permet pas de supprimer l’avertissement.
Les glucocorticoïdes peuvent masquer une infection et réactiver notamment la tuberculose ou l’hépatite B. Une exposition ou un risque de strongyloïdose doit être pris en compte avant de prolonger l’immunosuppression.''','aips-p8-prednisone_galepharm-5 aips-p8-prednisone_galepharm-6')+
tab(['Terrain ou interaction','Risque à anticiper','Conduite de sécurité'],[
(['Un diabète ou une hypertension est présent.','La prednisone peut aggraver le contrôle métabolique ou cardiovasculaire.','Contrôler régulièrement glycémie et pression artérielle et adapter le traitement associé si nécessaire.'],'aips-p8-prednisone_galepharm-6'),
(['Une insuffisance rénale est connue.','La notice exige une indication stricte et une surveillance étroite.','Individualiser la prescription ; aucune formule universelle de réduction rénale n’est fournie pour la PPR.'],'aips-p8-prednisone_galepharm-6'),
(['Une hypothyroïdie ou une cirrhose est présente.','L’effet des glucocorticoïdes peut être renforcé.','Une réduction de dose peut être nécessaire selon la notice.'],'aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6'),
(['Un inhibiteur puissant du CYP3A4 est associé.','L’exposition et les effets indésirables peuvent être modifiés.','La notice recommande d’éviter cette association, notamment avec certains azolés, macrolides, antiviraux ou produits contenant du cobicistat.'],'aips-p8-prednisone_galepharm-6 aips-p8-prednisone_galepharm-7'),
(['Des AINS ou des salicylés sont pris en parallèle.','Le risque ulcéreux et hémorragique digestif augmente.','Réévaluer leur nécessité et le risque digestif au lieu de les ajouter automatiquement contre les douleurs.'],'aips-p8-prednisone_galepharm-6 aips-p8-prednisone_galepharm-7'),
(['Une fluoroquinolone est prescrite.','L’association augmente le risque de tendinite et de rupture tendineuse.','Signaler la corticothérapie au prescripteur et réévaluer la combinaison.'],'aips-p8-prednisone_galepharm-6'),
(['Une grossesse survient ou est suspectée.','La notice décrit des risques fœtaux et néonataux sous exposition prolongée.','La prednisone ne doit être utilisée que si elle est clairement nécessaire ; informer immédiatement le médecin et individualiser la décision.'],'aips-p8-prednisone_galepharm-8'),
(['La personne allaite.','La prednisone passe dans le lait maternel.','La notice suisse demande de ne pas allaiter pendant l’utilisation systémique de corticostéroïdes.'],'aips-p8-prednisone_galepharm-8')])+
w(11,'Stress, infection et chirurgie : anticiper l’insuffisance surrénalienne','''La notice décrit une inhibition de l’axe corticosurrénalien après une exposition prolongée, pouvant persister jusqu’à une année ou davantage.
Une infection grave, un traumatisme ou une opération peut rendre nécessaire une supplémentation adaptée par l’équipe médicale. Le patient doit signaler sa corticothérapie actuelle et récente.
La fatigue ou les douleurs ne suffisent pas à distinguer une rechute inflammatoire d’un syndrome de sevrage. Une mauvaise tolérance lors de la diminution demande un avis, sans arrêt brutal ni escalade autonome.''','aips-p8-prednisone_galepharm-6 aips-p8-prednisone_galepharm-4 p8-eular-rechute')+
prose('''11.E — L’organisation ambulatoire suppose que l’urgence vasculaire a été évaluée, que la prescription est comprise et que le suivi est accessible. Ces conditions constituent une synthèse opérationnelle, pas un score de sortie validé.
Le patient doit connaître le nom et la dose actuelle du traitement, les étapes convenues de décroissance et la conduite en cas d’effet indésirable ou de manifestation nouvelle.
mediX propose des contrôles après une et quatre semaines, puis chaque mois durant la première année et tous les trois mois durant la seconde. Ce calendrier suisse est un repère organisationnel ; EULAR demande un suivi régulier adapté aux symptômes, à l’examen et aux marqueurs inflammatoires.
Les contrôles supplémentaires sont déclenchés par une manifestation nouvelle ou un effet indésirable. Les symptômes d’ACG ne doivent jamais attendre la prochaine visite programmée.''','p8-eular-education p8-ch-suivi p8-eular-r12 p8-eular-r2')+
tab(['Avant de poursuivre à domicile','Élément à vérifier','Si la condition manque'],[
(['L’urgence associée a été recherchée.','Les symptômes visuels, craniofaciaux et vasculaires ont une conduite explicite.','Organiser la filière urgente selon la suspicion, sans simple rendez-vous différé.'],'p8-eular-r2 p83-eular26-signes-urgence'),
(['Le projet diagnostique est compris.','Le patient sait si la PPR est confirmée ou encore en évaluation.','Compléter l’explication et organiser le recours spécialisé.'],'p8-eular-r1 p8-eular-partage'),
(['La prescription est réalisable.','La dose, le rythme et la décroissance sont identifiés avec le patient.','Résoudre la confusion avant de laisser une corticothérapie prolongée sans plan utilisable.'],'aips-p8-prednisone_galepharm-4 p8-eular-education'),
(['La surveillance est organisée.','Le prochain contrôle et le moyen de contacter l’équipe sont connus.','Adapter les modalités de prise en charge si le suivi ou l’aide nécessaire ne sont pas accessibles.'],'p8-ch-suivi p8-eular-education'),
(['Les signes imposant de revenir sont expliqués.','Le patient distingue rendez-vous programmé et nouvelle urgence visuelle ou effet indésirable sérieux.','Reprendre l’information et faire reformuler la conduite.'],'p8-eular-education p8-eular-r2 aips-p8-prednisone_galepharm-6')]))
put(12,prose('''La prévention primaire spécifique de la PPR n’est pas établie par un mécanisme causal unique permettant d’éviter la maladie. L’information ne doit pas promettre qu’un régime ou un médicament prévient son apparition.
La prévention secondaire consiste à reconnaître une présentation compatible et surtout une ACG associée. Elle évite qu’une douleur proximale réputée banale fasse méconnaître des symptômes ischémiques.
La prévention tertiaire porte sur les rechutes, le handicap et les complications des glucocorticoïdes. Elle commence dès l’initiation du traitement avec un projet de réduction de l’exposition et une surveillance adaptée.''','p8-mecanisme p8-eular-r1 p8-eular-r2 p8-eular-r3 aips-p8-prednisone_galepharm-6')+
tab(['Objectif','Mesure pratique','Limite et surveillance'],[
(['Détecter une ACG pendant le suivi.','Rechercher des symptômes visuels, céphalées nouvelles et claudication mandibulaire ; expliquer le recours urgent.','Une rémission des douleurs des ceintures ne dispense pas de surveiller les manifestations vasculaires.'],'p8-ch-suivi p8-eular-education p8-eular-r2'),
(['Préserver la santé osseuse.','Évaluer le risque de fracture et la nécessité d’une prophylaxie lorsque des glucocorticoïdes sont prolongés.','La notice souligne le risque accru après la ménopause et chez le patient âgé ; le traitement préventif est individualisé.'],'aips-p8-prednisone_galepharm-6 p8-ch-prevention'),
(['Limiter les complications métaboliques.','Surveiller poids, pression artérielle et glycémie, avec adaptation du traitement des comorbidités.','Une amélioration de la PPR n’annule pas une toxicité progressive des glucocorticoïdes.'],'aips-p8-prednisone_galepharm-6 p8-ch-suivi'),
(['Anticiper les infections et la vaccination.','Vérifier le statut vaccinal avant la corticothérapie lorsque cela est possible et tenir compte des infections latentes.','Les restrictions vaccinales de la notice, le type de vaccin et le calendrier demandent une vérification avant administration.'],'p8-ch-prevention aips-p8-prednisone_galepharm-5 aips-p8-prednisone_galepharm-6'),
(['Prévenir la perte fonctionnelle liée à une maladie insuffisamment contrôlée.','Revoir les activités devenues difficiles et les objectifs réalistes de récupération.','L’éducation explique que maladie et traitement peuvent limiter le retour complet à l’état antérieur.'],'p8-clinique p8-eular-education'),
(['Repérer une complication oculaire du traitement.','Organiser une surveillance ophtalmologique lors d’une corticothérapie prolongée et adresser en cas de trouble visuel.','Un trouble visuel peut aussi traduire une ACG : le contexte et l’urgence doivent être évalués.'],'p8-ch-suivi aips-p8-prednisone_galepharm-6 p8-eular-r2')])+
w(12,'Protection osseuse : évaluer avant de recopier une ordonnance','''mediX mentionne une prévention de l’ostéoporose lors d’une exposition à plus de 5 mg de prednisone par jour pendant plus de trois mois, avec calcium et vitamine D, et éventuellement un bisphosphonate selon les facteurs de risque.
Cette indication de prévention nécessite une évaluation clinique et une prescription propre au produit retenu. Elle ne fournit pas une dose universelle de supplément ou de bisphosphonate.
La notice de prednisone demande une indication stricte et une évaluation bénéfice-risque chez les patients particulièrement exposés à l’ostéoporose. La réduction de l’exposition aux glucocorticoïdes reste une partie de la prévention.''','p8-ch-prevention aips-p8-prednisone_galepharm-6 p8-eular-r3')+
w(12,'Vaccins et corticoïdes : ne pas confondre prévention et administration immédiate','''mediX recommande de mettre à jour les vaccinations en temps utile. La notice suisse de prednisone précise des restrictions autour des vaccinations prophylactiques lors d’un usage prolongé.
Elle cite environ huit semaines avant et jusqu’à deux semaines après ces vaccinations dans sa rubrique des contre-indications. Les précautions décrivent le risque infectieux des vaccins vivants et une réponse insuffisante aux vaccins inactivés.
Ces formulations doivent être confrontées au vaccin envisagé et à la situation clinique avant une décision individuelle. Elles ne justifient pas une injection automatique pendant une corticothérapie ni l’abandon définitif de la prévention vaccinale.''','p8-ch-prevention aips-p8-prednisone_galepharm-5 aips-p8-prednisone_galepharm-6')+
prose('''Une prophylaxie anti-infectieuse, une protection gastrique ou un traitement osseux éventuel doit être prescrit selon son indication et sa notice. Il ne faut pas attribuer à tous les patients le même ensemble de médicaments annexes.
mediX ne recommande pas d’antiagrégant, d’anticoagulant ou de statine uniquement du fait de la PPR en l’absence d’une autre indication. Les indications cardiovasculaires propres du patient restent traitées.
La prévention comprend enfin une information répétée sur le sevrage progressif et la conduite devant une maladie intercurrente. Le patient doit pouvoir signaler son exposition aux glucocorticoïdes à toute équipe qui le prend en charge.''','p8-ch-prevention p8-eular-education aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6'))
put(13,prose('''La PPR associe une douleur et une raideur inflammatoires des ceintures chez un patient généralement âgé, sans que la localisation musculaire des plaintes prouve une myopathie primitive.
La recherche d’une ACG, surtout devant un trouble visuel ou une claudication mandibulaire, détermine l’urgence et peut imposer des glucocorticoïdes sans attendre les examens confirmatoires.
Le diagnostic de PPR repose sur une constellation clinique et l’exclusion des imitateurs, alors que les critères de classification servent à la recherche et ne doivent pas devenir un test diagnostique.
Après confirmation, les glucocorticoïdes oraux sont ajustés au minimum efficace avec une décroissance individualisée et un objectif de rémission sans glucocorticoïdes.
Toute douleur récurrente demande de distinguer rechute, pathologie associée et difficulté de sevrage avant de modifier le traitement.
Le suivi associe récupération fonctionnelle, surveillance de l’inflammation, recherche de manifestations vasculaires et prévention des complications médicamenteuses.''','p8-clinique p8-dd-myosite p8-eular-r2 p83-eular26-diagnostic p8-eular-r3 p8-eular-r9 p8-eular-rechute p8-eular-r12'))
put(14,tab(['Question d’examen','Réponse justifiée','Piège à éviter'],[
(['Un score de classification positif suffit-il au diagnostic ?','Non : EULAR distingue explicitement classification et diagnostic individuel.','Le score ne remplace pas la recherche d’une polyarthrite, d’une myopathie ou d’une autre cause.'],'p83-eular26-diagnostic p8-classification'),
(['Pourquoi des douleurs décrites comme musculaires ne prouvent-elles pas une myosite ?','La PPR comporte des lésions synoviales et périarticulaires ; la force et les CK sont habituellement préservées.','Une vraie faiblesse ou des CK élevées demande une exploration distincte.'],'p8-mecanisme p8-dd-myosite p8-dgn-ck'),
(['Une CRP élevée confirme-t-elle la PPR ?','Non, elle documente une inflammation non spécifique.','Une infection, un cancer ou une autre maladie inflammatoire peut expliquer le résultat.'],'p8-bio p8-dd-cancer p8-dd-autres'),
(['Faut-il faire un essai de prednisone pour savoir ?','EULAR déconseille l’essai diagnostique de glucocorticoïdes avant l’évaluation de la PPR suspectée.','Une amélioration peut masquer des éléments nécessaires au diagnostic et n’est pas spécifique.'],'p8-eular-no-test p8-dd-pr'),
(['Quel symptôme fait changer immédiatement de filière ?','Un trouble visuel ou une autre manifestation ischémique évocatrice d’ACG impose une évaluation urgente.','La réduction des douleurs des épaules ne protège pas contre une vascularite associée.'],'p83-eular26-signes-urgence p8-eular-r2'),
(['L’échographie normale exclut-elle toute maladie ?','L’imagerie se lit avec la probabilité clinique ; une discordance nécessite une réévaluation.','Ni les anomalies des ceintures ni l’imagerie vasculaire ne doivent être lues hors contexte.'],'p8-imagerie p83-eular23-probabilite'),
(['Quelle est la cible à moyen terme sous traitement ?','EULAR vise la rémission sans glucocorticoïdes et propose l’arrêt dans l’année lorsque l’évolution le permet.','Un calendrier ne doit pas imposer l’arrêt malgré une activité persistante.'],'p8-eular-r3 p8-eular-taper'),
(['La notice de prednisone donne-t-elle le protocole spécifique EULAR ?','Non : l’AIPS fournit des modalités générales et des règles de sécurité ; EULAR précise le schéma clinique de PPR.','Ne pas attribuer à une notice un protocole qu’elle ne contient pas.'],'aips-p8-prednisone_galepharm-4 p8-eular-r3'),
(['Peut-on supprimer brutalement la prednisone quand le patient va mieux ?','Une exposition prolongée doit être diminuée progressivement selon la notice.','L’amélioration clinique ne démontre pas la récupération de l’axe corticosurrénalien.'],'aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6'),
(['Une rechute impose-t-elle automatiquement un biologique ?','Non : elle doit être évaluée et les options d’épargne sont discutées chez des patients sélectionnés.','La décision dépend aussi du diagnostic, des risques et du statut réglementaire.'],'p8-eular-r9 p8-eular-r6'),
(['Kevzara possède-t-il une indication suisse PPR dans la notice consultée ?','La notice suisse consultée indique la polyarthrite rhumatoïde, pas la PPR.','Une recommandation internationale ne modifie pas automatiquement une autorisation suisse.'],'aips-p8-kevzara-3'),
(['Une valeur inflammatoire persistante impose-t-elle toujours une augmentation de prednisone ?','Non : mediX recommande de tenir compte du bon état clinique pour éviter une exposition inutile.','Rechercher d’autres causes et interpréter l’ensemble des données.'],'p8-ch-suivi p8-eular-r9'),
(['Le suivi peut-il se limiter à la CRP ?','Non : EULAR demande symptômes, examen et marqueurs, avec attention aux complications du traitement.','Sous inhibition de l’IL-6, les marqueurs peuvent être particulièrement difficiles à interpréter.'],'p8-eular-r12 p8-eular-rechute'),
(['Pourquoi vérifier les autres médicaments ?','Certaines associations majorent les risques infectieux, digestifs, tendineux ou les effets de la prednisone.','Une prescription ancienne ne doit pas être supposée compatible sans vérification.'],'aips-p8-prednisone_galepharm-6 aips-p8-prednisone_galepharm-7'),
(['Un trouble visuel sous corticoïdes signifie-t-il forcément un effet secondaire ?','Non : une complication oculaire du traitement et une ACG sont deux hypothèses qui exigent une évaluation.','L’attribution au médicament ne doit pas retarder une urgence vasculaire.'],'aips-p8-prednisone_galepharm-6 p8-eular-r2'),
(['Pourquoi expliquer le traitement au patient à chaque étape ?','L’éducation aide à reconnaître rechute, urgence et effets indésirables et à suivre la décroissance.','L’absence de douleur au jour de la visite ne suffit pas à garantir un traitement compris.'],'p8-eular-education p8-eular-partage')]))
q='Ce cours, lu seul avec ses fenêtres, suffit-il pour gagner 90 à 100 % des points sur ce sujet et pour traiter ce patient en sécurité ?'
P=json.loads((D/'paquet.json').read_text());P['passages'].append(dict(id='p8-question-finale',source='Prompt de référence Vial, question finale obligatoire',url='',date='2026-11-10',texte=q));(D/'paquet.json').write_text(json.dumps(P,ensure_ascii=False,indent=2));REF['p8-question-finale']=str(len(P['passages']));f=F/'p14.html';f.write_text(f.read_text()+p(q,'p8-question-finale'))
